class Authenticator(Protocol):
    def authenticate(self, credential: Credential) -> Principal | None: ...

AUTHENTICATORS: dict[str, Authenticator] = {
    'password': PasswordAuthenticator(users),
    'bearer':   TokenAuthenticator(jwks, issuer),
    'mtls':     CertificateAuthenticator(trust_anchors),
}

def login(request) -> Principal | None:
    name, credential = negotiate(request)   # mechanism chosen by configuration / challenge
    return AUTHENTICATORS[name].authenticate(credential)
